/* Linker version script for dd's libcudart.so.
 *
 * An ANONYMOUS version node controls symbol *visibility* without appending an @@VERSION tag, so the
 * exported names read exactly like real libcudart's (plain `nm -D` names). Only the public runtime
 * `cuda*` entry points and the compiler-emitted `__cuda*` registration glue are global; every internal
 * helper (the error map, last-error TLS, the fatbin/func tables) is hidden. */
{
    global:
        cuda*;
        __cuda*;
    local:
        *;
};
